import { loadFont } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Audio, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";

// REFORMA LAR JF · OBRAS ENTREGUES (12/11/2026). Vitrine: 3 fotos e 15 vídeos de obras prontas, sem legenda do cliente.
// Identidade do logo novo (o da arte da Black Friday): preto, verde da casa, letra branca sem serifa com espaçamento largo
// e as linhas verdes dos lados de "LAR JF" (viraram o elemento-fio: toda etiqueta nasce entre duas linhas).
// Voz o locutor (src/novo/voz-v1.mp3, 42,2 s), com 1,6 s de silêncio morto tirado (voz-v1-edit.wav, 40,6 s).
// Referências: Giro Money (filmagem cheia + palavra-chave em tarja) e Ensaio de Aniversário (ritmo das fotos).
// Transições, uma diferente por troca e nenhuma das do Black Friday: casa (o formato do logo abrindo a cena), porta de
// correr, cortina lateral com linha verde, empurrão de baixo, zoom com desfoque, corte diagonal.

const { fontFamily: F } = loadFont("normal", { weights: ["500", "600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });

export const OB_FPS = 30;
const DUR = 41.4;
export const OB_FRAMES = Math.round(DUR * OB_FPS);

const G = "#1FA24C";
const GL = "#3DDB5A";
const BK = "#050806";
const W = "#FFFFFF";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const k = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const sp = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: Easing.out(Easing.back(0.9)) });
const TR = 0.38; // duração das transições

type Tr = "none" | "casa" | "porta" | "lateral" | "baixo" | "zoom" | "diag";
type Shot = { src: string; a: number; b: number; tr: Tr; from?: number; img?: boolean; pos?: string; z?: [number, number]; dim?: number };

// ordem das imagens (tempos já na voz editada)
const SHOTS: Shot[] = [
  { src: "led8", a: 0, b: 0.75, tr: "none", z: [1.18, 1.1] },
  { src: "coz5", a: 0.75, b: 1.45, tr: "porta" },
  { src: "box10", a: 1.45, b: 2.2, tr: "lateral" },
  { src: "banho6", a: 2.2, b: 3.3, tr: "zoom", dim: 0.55 },
  { src: "varanda2", a: 3.3, b: 4.85, tr: "casa" },
  { src: "box14", a: 4.85, b: 6.4, tr: "porta" },
  { src: "pia14", a: 6.4, b: 7.6, tr: "diag" },
  { src: "coz4", a: 7.6, b: 9.0, tr: "baixo" },
  { src: "casa13", a: 9.0, b: 10.3, tr: "lateral", from: 0.2 },
  { src: "quarto3", a: 10.3, b: 12.6, tr: "zoom" },
  { src: "sala15", a: 12.6, b: 13.9, tr: "casa" },
  { src: "led7", a: 13.9, b: 14.9, tr: "diag" },
  { src: "gour2", a: 14.9, b: 16.3, tr: "porta" },
  { src: "vista2", a: 16.3, b: 17.85, tr: "baixo" },
  { src: "escada13", a: 17.85, b: 18.8, tr: "lateral" },
  { src: "cafe.jpg", a: 18.8, b: 20.0, tr: "zoom", img: true, pos: "38% 50%" },
  { src: "pia.jpg", a: 20.0, b: 21.8, tr: "diag", img: true, pos: "50% 45%" },
  { src: "dourado11", a: 21.8, b: 23.4, tr: "porta" },
  { src: "caracol1", a: 23.4, b: 25.3, tr: "casa", dim: 0.5 },
  { src: "vista2b", a: 25.3, b: 27.9, tr: "baixo" },
  { src: "box10b", a: 27.9, b: 31.3, tr: "lateral", dim: 0.45 },
  { src: "led8b", a: 31.3, b: 34.4, tr: "zoom", dim: 0.5 },
  { src: "fecho2", a: 34.4, b: DUR, tr: "casa", dim: 0.72 },
];

// o formato da casa do logo (telhado + corpo), em % do quadro, para o clip-path crescer a partir do centro
const housePath = (s: number, cx = 540, cy = 980) => {
  const pts = [[0, -1.05], [0.62, -0.42], [0.62, 0.62], [-0.62, 0.62], [-0.62, -0.42]];
  return `polygon(${pts.map(([x, y]) => `${(cx + x * s).toFixed(1)}px ${(cy + y * s).toFixed(1)}px`).join(",")})`;
};

const clipFor = (tr: Tr, p: number): { clip?: string; extra?: React.CSSProperties } => {
  if (p >= 1 || tr === "none") return {};
  const e = OUT(p);
  switch (tr) {
    case "casa":
      return { clip: housePath(interpolate(p, [0, 1], [0, 3000], { ...cl, easing: Easing.in(Easing.quad) })) };
    case "porta":
      return { clip: `inset(0 ${(50 * (1 - e)).toFixed(2)}% 0 ${(50 * (1 - e)).toFixed(2)}%)` };
    case "lateral":
      return { clip: `inset(0 0 0 ${(100 * (1 - e)).toFixed(2)}%)` };
    case "baixo":
      return { extra: { transform: `translateY(${((1 - e) * 100).toFixed(2)}%)` } };
    case "zoom":
      return { extra: { opacity: Math.min(1, p * 2.2), filter: `blur(${((1 - e) * 14).toFixed(1)}px)`, transform: `scale(${(1 + (1 - e) * 0.28).toFixed(3)})` } };
    case "diag": {
      const x = (1 - e) * 1700;
      return { clip: `polygon(${(x - 400).toFixed(0)}px 0, 1480px 0, 1480px 1920px, ${(x - 1000).toFixed(0)}px 1920px)` };
    }
  }
  return {};
};

// a linha verde que acompanha a borda de cada cortina
const Edge: React.FC<{ tr: Tr; p: number }> = ({ tr, p }) => {
  if (p <= 0 || p >= 1) return null;
  const e = OUT(p);
  const line = (x: number, key: string) => <div key={key} style={{ position: "absolute", top: 0, bottom: 0, left: x - 5, width: 10, background: GL }} />;
  if (tr === "porta") return <>{[line(540 - 540 * e, "l"), line(540 + 540 * e, "r")]}</>;
  if (tr === "lateral") return line(1080 * (1 - e), "l");
  if (tr === "baixo") return <div style={{ position: "absolute", left: 0, right: 0, top: 1920 * (1 - e) - 5, height: 10, background: GL }} />;
  return null;
};

const ShotView: React.FC<{ s: Shot; t: number }> = ({ s, t }) => {
  if (t < s.a || t >= s.b + TR + 0.05) return null;
  const p = s.tr === "none" ? 1 : lin(t, s.a, s.a + TR);
  const { clip, extra } = clipFor(s.tr, p);
  const z = s.z ?? [1.03, 1.13];
  const sc = z[0] + (z[1] - z[0]) * lin(t, s.a, s.b + TR);
  const dim = s.dim ?? 0.28;
  const media: React.CSSProperties = { position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", objectPosition: s.pos ?? "50% 50%", transform: `scale(${sc.toFixed(4)})` };
  return (
    <AbsoluteFill style={{ clipPath: clip, overflow: "hidden", background: BK, ...extra }}>
      {s.img ? (
        <Img src={staticFile(`reformalar/n/${s.src}`)} style={media} />
      ) : (
        <Sequence from={Math.round(s.a * OB_FPS)} layout="none">
          <OffthreadVideo src={staticFile(`reformalar/n/${s.src}.mp4`)} trimBefore={Math.round((s.from ?? 0) * OB_FPS)} muted style={media} />
        </Sequence>
      )}
      {/* degradê leve: escurece pouco, mais embaixo, onde mora o lettering */}
      <AbsoluteFill style={{ background: `linear-gradient(180deg, rgba(5,8,6,${(dim * 0.5).toFixed(2)}) 0%, rgba(5,8,6,${(dim * 0.25).toFixed(2)}) 40%, rgba(5,8,6,${(dim + 0.18).toFixed(2)}) 78%, rgba(5,8,6,${Math.min(0.85, dim + 0.35).toFixed(2)}) 100%)` }} />
    </AbsoluteFill>
  );
};

// ---------- lettering ----------
const sh = "0 3px 14px rgba(0,0,0,0.7), 0 0 3px rgba(0,0,0,0.5)";
const fit = (txt: string, max: number, width = 820, ratio = 0.74) => Math.min(max, Math.floor(width / (txt.length * ratio)));

// texto que nasce de baixo da linha e fica parado
const Up: React.FC<{ t: number; at: number; d?: number; children: React.ReactNode }> = ({ t, at, d = 0.42, children }) => {
  const e = k(t, at, d);
  return (
    <div style={{ overflow: "hidden", padding: "0.1em 0.25em", margin: "-0.1em -0.25em" }}>
      <div style={{ transform: `translateY(${((1 - e) * 112).toFixed(1)}%)`, opacity: t >= at ? 1 : 0 }}>{children}</div>
    </div>
  );
};

// etiqueta pequena entre duas linhas verdes (as linhas do "LAR JF" do logo)
const Tag: React.FC<{ t: number; at: number; text: string; size?: number }> = ({ t, at, text, size = 34 }) => {
  const e = k(t, at, 0.5);
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 22 }}>
      <div style={{ width: 90 * e, height: 5, background: GL, borderRadius: 3 }} />
      <Up t={t} at={at + 0.05}>
        <div style={{ fontFamily: F, fontWeight: 700, fontSize: size, letterSpacing: "0.28em", marginRight: "-0.28em", color: W, textTransform: "uppercase", whiteSpace: "nowrap", textShadow: sh }}>{text}</div>
      </Up>
      <div style={{ width: 90 * e, height: 5, background: GL, borderRadius: 3 }} />
    </div>
  );
};

// título no bloco verde: o bloco abre do centro e a palavra sobe por dentro
const Block: React.FC<{ t: number; at: number; text: string; max?: number }> = ({ t, at, text, max = 132 }) => {
  const size = fit(text, max);
  const e = k(t, at, 0.36);
  return (
    <div style={{ position: "relative", padding: `${size * 0.16}px ${size * 0.34}px ${size * 0.2}px` }}>
      <div style={{ position: "absolute", inset: 0, background: G, borderRadius: size * 0.14, transform: `scaleX(${e.toFixed(3)})`, boxShadow: "0 18px 40px rgba(0,0,0,0.35)" }} />
      <div style={{ position: "relative" }}>
        <Up t={t} at={at + 0.08}>
          <div style={{ fontFamily: F, fontWeight: 900, fontSize: size, lineHeight: 1, color: W, textTransform: "uppercase", whiteSpace: "nowrap", letterSpacing: "-0.005em" }}>{text}</div>
        </Up>
      </div>
    </div>
  );
};
const Sub: React.FC<{ t: number; at: number; text: string; size?: number; color?: string }> = ({ t, at, text, size = 62, color = W }) => (
  <Up t={t} at={at}>
    <div style={{ fontFamily: F, fontWeight: 700, fontSize: Math.min(size, fit(text, size, 860, 0.6)), lineHeight: 1.1, color, whiteSpace: "nowrap", textShadow: sh, textAlign: "center" }}>{text}</div>
  </Up>
);

// cada lettering ocupa a mesma coluna embaixo; some inteiro (desce pela máscara) antes do próximo
const Lower: React.FC<{ t: number; a: number; b: number; top?: number; children: React.ReactNode }> = ({ t, a, b, top = 1170, children }) => {
  if (t < a || t >= b) return null;
  const x = interpolate(t, [b - 0.16, b], [0, 1], { ...cl, easing: Easing.in(Easing.quad) });
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap: 26, opacity: 1 - x, transform: `translateY(${(x * 30).toFixed(1)}px)` }}>
      {children}
    </div>
  );
};

const Logo: React.FC<{ t: number; at: number; w: number }> = ({ t, at, w }) => {
  const e = sp(t, at, 0.55);
  const m = k(t, at, 0.5);
  return (
    <div style={{ width: w, opacity: t >= at ? 1 : 0, transform: `scale(${(0.82 + 0.18 * e).toFixed(4)})`, clipPath: `inset(${((1 - m) * 100).toFixed(1)}% 0 0 0)`, filter: "drop-shadow(0 12px 40px rgba(0,0,0,0.55))" }}>
      <Img src={staticFile("reformalar/n/logo.png")} style={{ width: "100%", display: "block" }} />
    </div>
  );
};

const Pin: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s * 1.3} viewBox="0 0 40 52">
    <path d="M20 2C10 2 3 9.5 3 19c0 12.5 17 31 17 31s17-18.5 17-31C37 9.5 30 2 20 2z" fill={G} stroke={W} strokeWidth={2.5} />
    <circle cx={20} cy={19} r={6.5} fill={W} />
  </svg>
);
const WaIcon: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 48 48">
    <path d="M24 5a19 19 0 0 0-16.3 28.8L5 43l9.5-2.6A19 19 0 1 0 24 5z" fill={W} />
    <path d="M18 15.5c-.5-1-1-1-1.4-1h-1.2c-.5 0-1.1.1-1.7.8-.6.6-2.2 2.1-2.2 5.200s2.200 6 2.500 6.500c.3.400 4.300 6.900 10.700 9.400 5.300 2.100 6.400 1.700 7.500 1.600 1.100-.1 3.700-1.500 4.200-3 .5-1.500.5-2.700.4-3-.2-.3-.5-.4-1.200-.7l-4.200-2c-.6-.2-1-.3-1.400.3-.5.6-1.600 2-1.900 2.400-.4.400-.7.500-1.400.200-.6-.3-2.600-1-5-3.100-1.900-1.600-3.100-3.700-3.400-4.300-.4-.6 0-.9.300-1.200.300-.3.600-.7.900-1.100.3-.4.400-.6.600-1 .2-.5.1-.8-.1-1.100z" fill={G} />
  </svg>
);

const Count: React.FC<{ t: number; at: number }> = ({ t, at }) => {
  const n = Math.round(interpolate(t, [at - 0.6, at], [1, 12], { ...cl, easing: OUT }));
  const e = sp(t, at - 0.6, 0.5);
  return (
    <div style={{ display: "flex", alignItems: "baseline", gap: 18, opacity: t >= at - 0.6 ? 1 : 0, transform: `scale(${(0.85 + 0.15 * e).toFixed(4)})` }}>
      <div style={{ fontFamily: F, fontWeight: 900, fontSize: 250, lineHeight: 0.9, color: W, textShadow: sh, fontVariantNumeric: "tabular-nums" }}>
        <span style={{ color: GL }}>+</span>
        {String(n).padStart(2, "0")}
      </div>
      <div style={{ fontFamily: F, fontWeight: 900, fontSize: 92, color: W, textShadow: sh }}>ANOS</div>
    </div>
  );
};

