  return (
    <>
      <Lower t={t} a={0} b={1.42} top={1040}>
        {[hook.slice(0, 2), hook.slice(2)].map((row, r) => (
          <div key={r} style={{ display: "flex", gap: 30, marginTop: r ? -10 : 0 }}>
            {row.map(([w, at]) => (
              <Up key={w} t={t} at={at} d={0.3}>
                <div style={{ fontFamily: F, fontWeight: 900, fontSize: 128, lineHeight: 1, color: W, textShadow: sh }}>{w}</div>
              </Up>
            ))}
          </div>
        ))}
        <Tag t={t} at={0.88} text="uma obra da" />
      </Lower>
      {t >= 1.45 && t < 3.32 ? (
        <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", opacity: 1 - lin(t, 3.12, 3.3), background: `radial-gradient(circle at 50% 50%, rgba(5,8,6,${(0.62 * k(t, 1.45, 0.3)).toFixed(2)}) 0%, rgba(5,8,6,0) 62%)` }}>
          <Logo t={t} at={1.48} w={760} />
        </AbsoluteFill>
      ) : null}
      <Lower t={t} a={3.5} b={4.86}>
        <Block t={t} at={3.52} text="Olha só" max={150} />
      </Lower>

      <Lower t={t} a={4.9} b={7.58}>
        <Block t={t} at={4.92} text="Banheiros" />
        <Sub t={t} at={5.55} text="com acabamento que impressiona" />
      </Lower>
      <Lower t={t} a={7.66} b={10.28}>
        <Block t={t} at={7.68} text="Cozinhas" />
        <Sub t={t} at={8.2} text="prontas para receber a família" />
      </Lower>
      <Lower t={t} a={10.36} b={12.58}>
        <Block t={t} at={10.4} text="Quartos" />
        <Sub t={t} at={11.12} text="aconchegantes" />
      </Lower>
      <Lower t={t} a={12.7} b={14.88}>
        <Block t={t} at={12.74} text="Salas" />
        <Sub t={t} at={13.3} text="com iluminação em LED" />
      </Lower>
      <Lower t={t} a={15.0} b={17.83}>
        <Block t={t} at={15.34} text="Áreas gourmet" />
        <Sub t={t} at={16.5} text="com vista" />
      </Lower>
      <Lower t={t} a={17.9} b={19.98}>
        <Tag t={t} at={17.92} text="do residencial" size={38} />
        <Block t={t} at={18.82} text="ao comercial" />
      </Lower>
      <Lower t={t} a={20.0} b={21.78}>
        <Block t={t} at={20.02} text="Cada detalhe" />
        <Sub t={t} at={20.9} text="executado por uma" />
      </Lower>
      <Lower t={t} a={21.82} b={23.38}>
        <Block t={t} at={21.84} text="Equipe completa" />
      </Lower>
      <Lower t={t} a={23.45} b={25.28} top={1080}>
        <Count t={t} at={24.33} />
        <Tag t={t} at={24.8} text="transformando espaços" size={32} />
      </Lower>
      <Lower t={t} a={25.35} b={27.88}>
        <div style={{ ...{ opacity: t >= 25.9 ? 1 : 0, transform: `translateY(${((1 - sp(t, 25.9, 0.45)) * -60).toFixed(1)}px)` } }}>
          <Pin s={74} />
        </div>
        <Block t={t} at={26.15} text="Juiz de Fora" />
        <Sub t={t} at={27.28} text="e região" size={60} />
      </Lower>
      <Lower t={t} a={28.0} b={31.28} top={1090}>
        <Tag t={t} at={28.3} text="você parcela em" size={36} />
        <div style={{ display: "flex", alignItems: "baseline", gap: 24 }}>
          <Up t={t} at={29.66}>
            <div style={{ fontFamily: F, fontWeight: 800, fontSize: 84, color: W, textShadow: sh }}>ATÉ</div>
          </Up>
          <div style={{ opacity: t >= 30.12 ? 1 : 0, transform: `scale(${(0.7 + 0.3 * sp(t, 30.12, 0.4)).toFixed(4)})` }}>
