          <WaIcon s={84} />
          <div style={{ fontFamily: F, fontWeight: 900, fontSize: 58, color: W, whiteSpace: "nowrap" }}>CHAMA NO WHATSAPP</div>
        </div>
        <Sub t={t} at={32.05} text="(00) 00000-0000" size={78} />
        <Tag t={t} at={32.82} text="solicite seu orçamento" size={32} />
      </Lower>
      {/* fecho: logo e assinatura */}
      {t >= 34.9 ? (
        <div style={{ position: "absolute", left: 120, right: 120, top: 470, display: "flex", flexDirection: "column", alignItems: "center", gap: 70 }}>
          <Logo t={t} at={34.95} w={760} />
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 14 }}>
            <Up t={t} at={37.04}>
              <div style={{ fontFamily: F, fontWeight: 600, fontSize: 58, color: W, textShadow: sh, whiteSpace: "nowrap" }}>Nós cuidamos da</div>
            </Up>
            <Up t={t} at={38.36}>
              <div style={{ fontFamily: F, fontWeight: 900, fontSize: 86, color: GL, textShadow: sh, whiteSpace: "nowrap" }}>TRANSFORMAÇÃO</div>
            </Up>
            <Up t={t} at={39.94}>
              <div style={{ fontFamily: F, fontWeight: 600, fontSize: 58, color: W, textShadow: sh, whiteSpace: "nowrap" }}>do seu espaço.</div>
            </Up>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 16, opacity: k(t, 37.3, 0.5) }}>
            <WaIcon s={50} />
            <div style={{ fontFamily: F, fontWeight: 700, fontSize: 44, color: W, textShadow: sh }}>(00) 00000-0000</div>
          </div>
        </div>
      ) : null}
    </>
  );
};

export const ReformaLarObras: React.FC = () => {
  const t = useCurrentFrame() / OB_FPS;
  return (
    <AbsoluteFill style={{ background: BK, fontFamily: F }}>
      {SHOTS.map((s, i) => (
        <ShotView key={i} s={s} t={t} />
      ))}
      {SHOTS.map((s, i) => (t >= s.a && t < s.a + TR ? <Edge key={`e${i}`} tr={s.tr} p={lin(t, s.a, s.a + TR)} /> : null))}
      <Texts t={t} />
      <Audio src={staticFile("reformalar/n/voz.wav")} />
    </AbsoluteFill>
  );
};

import React from "react";
import { Composition, registerRoot } from "remotion";
import { OB_FPS, OB_FRAMES, ReformaLarObras } from "./Obras";

const Root: React.FC = () => (
  <>
    <Composition id="ReformaLarObras" component={ReformaLarObras} durationInFrames={OB_FRAMES} fps={OB_FPS} width={1080} height={1920} />
  </>
);
registerRoot(Root);
